ddress":"3850 Avenida Vasco De Quiroga, Unidad 1046, Santa Fe, Cuajimalpa De Morelos, Ciudad De México 05348","map_addr_1":"3850 Avenida Vasco De Quiroga","map_addr_2":"Unidad 1046","map_city_state_zip":"Santa Fe, Cuajimalpa De Morelos, Ciudad De México 05348","grid_brand":"Planet Fitness","is_next_percent_rent_payment":"No","location_created_at":"2026-05-26 19:29:07","active_lease_count_over_time":61278,"location_count_over_time":67831,"remaining_rent_liability_over_time":61278,"base_rent_next_month":"475000.0000"}'::jsonb);
