INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('4cfc8e97-dadb-4c20-b728-33859f25bf1e', 'Fecha de Firma del Contrato', '17 de febrero de 2026', 'America Gonzalez', NULL);
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('4cfc8e97-dadb-4c20-b728-33859f25bf1e', 'Percentage Rent', '3', 'SEGUNDA', 'RENTA', E'- La subarrendataria paga una Renta Mínima mensual.\n- También paga una Renta Variable del 8% de sus ventas netas.\n- Si la Renta Variable es mayor que la Renta Mínima, paga la diferencia más IVA en los primeros 15 días del mes siguiente.\n- Debe entregar un reporte de ventas mensual en los primeros 10 días.\n- Debe tener la documentación disponible para revisión.', E'La subarrendataria debe pagar mensualmente la Renta Mínima y, adicionalmente, una Renta Variable equivalente al 8% de sus ventas netas. Cada mes, la subarrendadora compara ambos montos, si la renta variable es mayor a la renta mínima, la subarrendataria debe pagar la diferencia más IVA dentro de los primeros 15 días del mes siguiente.\n\nLa subarrendataria debe entregar un reporte mensual de ventas dentro de los primeros 10 días.\nTener disponible la documentación para revisión.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('4cfc8e97-dadb-4c20-b728-33859f25bf1e', 'Inversión', '4', 'SEGUNDA TER', 'INVERSIÓN A CUENTA DE RENTAS', E'- The subtenant will invest $5,400,000 plus VAT to prepare the space (clean shell).\n- This investment will count towards the minimum rent payment.\n- Payment will be made in three installments of $1,800,000 plus VAT: at signing, 30 days, and 60 days.\n- The investment will be offset by monthly amortization of $225,000 plus VAT over 24 months, credited towards rent.', 'La subarrendataria asumirá con recursos propios la inversión para el acondicionamiento (clean shell) del local, estimada en $5,400,000 + IVA, la cual se aplicará como pago a cuenta de la renta mínima. El pago de esta inversión se realizará en tres exhibiciones de $1,800,000 + IVA (a la firma, a 30 días y a 60 días). Posteriormente, se compensará mediante la amortización mensual de $225,000 + IVA durante 24 meses, a cuenta de rentas.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('4cfc8e97-dadb-4c20-b728-33859f25bf1e', 'Incremento de Renta', '7', 'Sexta', 'INCREMENTO DE LA RENTA', E'- The Minimum Rent will be adjusted every year starting from the first anniversary of the opening.\n- The adjustment is based on the change in the Consumer Price Index (INPC) of Mexico City over the past 12 months.\n- If the INPC reaches or exceeds 10% before six months, the increase will be applied immediately.', 'La Renta Mínima se ajustará anualmente desde el primer aniversario de la apertura, conforme a la variación del INPC de la Ciudad de México de los últimos 12 meses. Si el INPC alcanza o supera el 10% antes de seis meses, el incremento se aplicará de inmediato en ese momento.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('4cfc8e97-dadb-4c20-b728-33859f25bf1e', 'Common Area Maintenance Charges', '8', 'NOVENA', 'CUOTA DE ADMINISTRACIÓN Y MANTENIMIENTO', E'- The subtenant must pay a monthly administration and maintenance fee in addition to the rent.\n- This fee is 10% of the current minimum rent plus VAT.\n- Payment is due in the same manner and on the same date as the rent.\n- The fee covers costs for managing, operating, and maintaining common areas like parking, access points, gardens, and restrooms.\n- It also includes services such as security, cleaning, repairs, insurance, and equipment.', 'La subarrendataria deberá pagar, además de la renta, una cuota mensual de administración y mantenimiento equivalente al 10% de la renta mínima vigente más IVA, en la misma forma y fecha de pago. Esta cuota cubre los costos de administración, operación y mantenimiento de las áreas comunes del centro comercial, como estacionamientos, accesos, jardines, sanitarios, entre otros, así como servicios como vigilancia, limpieza, reparaciones, seguros y equipo.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('4cfc8e97-dadb-4c20-b728-33859f25bf1e', 'Hours of Operation', '9', 'DÉCIMA TERCERA', 'OTROS GASTOS', E'- La subarrendataria puede operar el local 24 horas al día, 5 días a la semana.\n- También puede operar fines de semana y días festivos, excepto el 25 de diciembre y el 1 de enero.\n- Los días 24 y 31 de diciembre puede operar con horario reducido.\n- Si opera fuera de los horarios permitidos por el centro comercial, después de seis meses de operación, se acordará un pago adicional por gastos extra como electricidad y personal.', 'La subarrendataria está autorizada a operar el local 24 horas, 5 días a la semana, así como fines de semana y días festivos, excepto el 25 de diciembre y 1 de enero; los días 24 y 31 de diciembre podrá operar con horario reducido. Si opera en horarios extendidos fuera de lo permitido por la normatividad del centro comercial, las partes acordarán, después de los primeros seis meses de operación, el pago adicional por gastos como electricidad, personal extra y otros costos derivados.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('4cfc8e97-dadb-4c20-b728-33859f25bf1e', 'Parking', '9', 'Décima tercera', 'OTROS GASTOS', E'- Los clientes de la subarrendataria pagan $10 por los primeros 120 minutos de estacionamiento.\n- Después de 120 minutos, se aplica la tarifa normal de estacionamiento.\n- Tras seis meses, se revisarán los boletos usados para calcular un pago mensual adicional, solo considerando boletos entre las 11:00 y las 20:00.\n- Los costos pueden ajustarse si cambian los gastos relacionados, y se notificará a la subarrendataria sobre estos cambios.', E'Se establece una tarifa preferencial de estacionamiento de $10 por los primeros 120 minutos para clientes de la subarrendataria; a partir del minuto 121 se aplica la tarifa normal.\nAl finalizar los primeros seis meses de operación, las partes revisarán los boletos utilizados para determinar un pago mensual adicional por este beneficio, considerando únicamente los boletos dentro del horario normal (11:00 a 20:00).\nLos costos previstos podrán ajustarse conforme cambien los gastos relacionados, y dichos cambios serán informados oportunamente a la subarrendataria.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('4cfc8e97-dadb-4c20-b728-33859f25bf1e', 'Late Fees', '10', 'Décima sexta', 'INTERESES MORATORIOS', E'- Si la subarrendataria no paga, paga tarde o paga solo una parte, deberá pagar intereses adicionales.\n- Los intereses se calculan usando el CPP del Banco de México multiplicado por 1.33.\n- Si el CPP es menor al 30%, se usará el 30% como base para el cálculo.\n- La tasa resultante se divide entre 12 y se aplica mensualmente al monto adeudado.\n- Si no hay CPP, se usará la tasa de CETES a 28 días.', 'En caso de incumplimiento, pago parcial o retraso en obligaciones económicas, la subarrendataria deberá pagar intereses moratorios calculados con base en el CPP del Banco de México multiplicado por 1.33. Si el CPP es menor al 30%, se aplicará como base ese 30% multiplicado por 1.33, la tasa resultante se divide entre 12 y se aplica mensualmente al adeudo pendiente por cada mes o fracción de atraso. Si no existe CPP, se usará la tasa de CETES a 28 días.');
