_count_over_time":68141,"remaining_rent_liability_over_time":61530}'::jsonb);
INSERT INTO leases (id, location_id, tenant_company_id, lease_name, lease_type, is_sub_lease, estatus, acquisition_type, lease_classification, rent_commencement_date, delivery_date, expiration_date, expiration_date_including_options, is_month_to_month, number_of_options, each_option_years, remaining_options, remaining_options_years, renewal_notice_period_start, renewal_notice_deadline, renewal_notice_intention, length_of_lease_months, landlord_nombre, landlord_parent_company, landlord_vendor_id, landlord_address1, landlord_address2, landlord_city, landlord_state, landlord_zip, landlord_country, landlord_poc_nombre, landlord_poc_telefono, landlord_poc_email, grace_period_dias, late_fee_type, late_fee_monto, security_deposit, rental_prepayments, rental_prepayments_detalle, remaining_lease_liability, percent_rent_yn, atributos_extra) VALUES ('68792a09-d59d-4bea-8def-c9a2ffaa330b', '85868bcc-b2c2-4fe7-a387-7421ce13d4f7', '83602737-ca9f-417e-b1ac-19d0ad371be6', 'Izazaga Lease: San Ignacio de Loyola Vizcaínas, IAP', NULL, false, 'activo', 'Lease', NULL, NULL, NULL, NULL, NULL, false, 1, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'San Ignacio de Loyola Vizcaínas, IAP', NULL, NULL, 'Vizcaínas 21, colonia Centro, C.P. 06080, Alcaldía Cuahutémoc, CDMX', NULL, NULL, NULL, NULL, 'MX', NULL, NULL, NULL, 180, 'percent', NULL, NULL, 791825, 'La Arrendataria se obliga a pagar a la Arrendadora a la entrega del Local, la cantidad de $ 791,825.00 (Setecientos noventa y un mil ochocientos veinticinco pesos 00/100, M.N.) más el Impuesto Al Valor Agregado, equivalente a 2 (dos) meses de Renta, la cual se aplicará, bajo el mismo concepto, para los dos primeros meses de Renta.', NULL, false, '{"lease_most_recent_note":"No","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1,"rent_commencement_date_original":"TBD","expiration_date_original":"TBD","expiration_date_including_options_original":"TBD"}'::jsonb);
