INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('68792a09-d59d-4bea-8def-c9a2ffaa330b', 'Fecha de Firma del Contrato', '23 de abril de 2026', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('68792a09-d59d-4bea-8def-c9a2ffaa330b', 'Fecha de entrega del inmueble', 'Una vez que la Arrendataria obtenga los permisos, licencias y autorizaciones requeridas para la adaptación del INMUEBLE', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('68792a09-d59d-4bea-8def-c9a2ffaa330b', 'Fecha de inicio de pago de renta', 'A la fecha de término del periodo de gracia', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('68792a09-d59d-4bea-8def-c9a2ffaa330b', 'Vigencia', '10 años forzosos para ambas partes contados a partir de la fecha de entrega del Inmueble', 'America Gonzalez', NULL);
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('68792a09-d59d-4bea-8def-c9a2ffaa330b', 'Common Area Maintenance Charges', '4', 'Tercera', 'SEGURIDAD Y MANTENIMIENTO', E'- The tenant is responsible for maintaining the property during the lease term.\n- Maintenance includes conservation, cleaning, security, lighting, and appearance.\n- The tenant must handle necessary repairs due to normal wear and tear.\n- The tenant is also responsible for operating, monitoring, managing, and collecting fees for the property''s parking.', 'Las Partes acuerdan que durante la vigencia del Contrato, conforme al plazo señalado en el Apartado 12 de la Carátula, será a cargo de la Arrendataria el mantenimiento del Inmueble, entendiendo por éste la conservación, limpieza, seguridad, iluminación e imagen y aquellos trabajos necesarios para su correcto uso y funcionamiento derivados del desgaste normal por el uso, así como la operación, vigilancia, administración y cobro del estacionamiento del Inmueble.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('68792a09-d59d-4bea-8def-c9a2ffaa330b', 'Right of Occupancy', '4', 'Quinta Bis', 'DERECHO DE PERMANENCIA', E'- The landlord plans to develop a shopping center with parking on the property.\n- The tenant has the following rights:\n  1. Continue leasing if the landlord decides to keep renting the property.\n  2. First right to buy the property.\n  3. Participate in the shopping center project and have a similar space reinstated.\n  4. If the shopping center is developed, the tenant will be relocated to a similar space, with relocation costs covered by the landlord.\n- Terms for extension or relocation will be agreed upon, except for rent increases, which follow Clause Six.\n- If the tenant exercises the right to buy, terms will be agreed upon.\n- If the landlord ends the contract during the extension period:\n  - It can only be ended after year 12.\n  - The tenant must be notified 12 months in advance.\n  - If ended in year 13, the landlord pays the tenant $10,000,000 plus VAT.\n  - If ended in year 14, the landlord pays the tenant $5,000,000 plus VAT.', E'Las Partes reconocen que la Arrendadora ha manifestado su intención de desarrollar un centro comercial con estacionamiento en el INMUEBLE (en lo sucesivo, el "Centro Comercial").\nEn virtud de lo anterior, la Arrendataria contará con los siguientes derechos:\n1. Continuar con el arrendamiento por el periodo que las Partes acuerden en caso de que la Arrendadora decida continuar arrendando el Inmueble.\n2. Derecho del tanto para adquirir el Inmueble.\n3. Participar en el proyecto para la construcción del Centro Comercial por su cuenta o a través de un tercero, y la reinstalación de un local para la Arrendataria en condiciones similares a las del INMUEBLE. \n4. Si la Arrendadora desarrolla el Centro Comercial, reubicará a la Arrendataria en un local con condiciones físicas similares o iguales a las del INMUEBLE. Las erogaciones que deriven de la reubicación de la Arrendataria, tales como adecuación, decoración interior y exterior, infraestructura, reinstalación de equipo y muebles existentes en el INMUEBLE, serán a cargo de la Arrendadora.\n\nPara los supuestos 1, 3 y 4, las Partes acordarán los términos y condiciones de la prórroga y/o o reubicación, con excepción del incremento de la renta, para lo cual las Partes se obligan a los establecido en la Cláusula Sexta. En el supuesto del numeral 2, si la Arrendataria ejerce el derecho del tanto, las partes acordaran los términos respectivos.\n\nEn caso de que la Arrendadora decida dar por terminado el presente Contrato durante el periodo de prórroga, deberá sujetarse a lo siguiente:\n\ni) Únicamente podrá darlo por terminado después de concluir el año 12 (doce) de vigencia del Contrato: \nii) deberá notificarlo por escrito a la Arrendataria con al menos 12 (doce) meses de anticipación la fecha efectiva de terminación; \niii) si la terminación ocurre durante el año 13 (trece), la Arrendadora se obliga a pagar a la Arrendataria la cantidad de $10,000,000.00 (Diez millones de pesos 00/100 M.N.) mas el Impuesto al Valor Agregado: y \niv)si la terminación ocurre durante el año 14 (catorce), la Arrendadora se obliga a pagar a la Arrendataria la cantidad de $5,000,000.00 (Cinco millones de pesos 00/100 M.N.) mas el Impuesto al Valor Agregado.');
